mkconf() { d=$1; rpc=$2; p2p=$3; zmq=$4; rm -rf $d; mkdir -p $d; { echo "regtest=1"; echo "[regtest]"; echo "server=1"; echo "listen=1"; echo "bind=127.0.0.1"; echo "port=$p2p"; echo "rpcuser=poc"; echo "rpcpassword=pocpass"; echo "rpcport=$rpc"; echo "rpcbind=127.0.0.1"; echo "rpcallowip=127.0.0.1"; echo "dnsseed=0"; echo "debug=smsg"; echo "fallbackfee=0.0001"; for t in hashblock rawblock hashtx rawtx hashtxlock rawtxlock rawtxlocksig hashchainlock rawchainlock rawchainlocksig hashgovernanceobject rawgovernanceobject hashgovernancevote rawgovernancevote hashinstantsenddoublespend rawinstantsenddoublespend hashrecoveredsig rawrecoveredsig hashsmsg rawsmsg; do echo "zmqpub$t=tcp://127.0.0.1:$zmq"; done; } > $d/omega.conf; }
waitup() { for i in $(seq 1 80); do $1 getblockcount >/dev/null 2>&1 && return 0; python3 -I -c "import time; time.sleep(0.5)"; done; return 1; }
